summary_score<-function(d,branch){rbindlist(lapply(c('UCell','NMF'),function(s){field<-if(s=='UCell')'ucell10'else'usage10';x<-d[,.(n=.N,mean=mean(get(field)),median=median(get(field)),q25=quantile(get(field),.25,type=7),q75=quantile(get(field),.75,type=7),zero_fraction=mean(get(field)==0)),by=cluster];setorder(x,-mean,cluster);x[,`:=`(rank=.I,score=s,branch=branch)];x}))}
