 q<-sp[eligible==TRUE];dd<-q$difference;exact<-length(dd)>0&&!any(dd==0)&&!anyDuplicated(abs(dd));test<-if(length(dd)>0 && any(dd!=0))wilcox.test(q$K32_mean,q$control_mean,paired=TRUE,alternative='two.sided',exact=exact,correct=!exact)else NULL
 tests[[paste(br,score)]]<-data.table(branch=br,score=score,control=control,n_pairs=nrow(q),n_datasets=uniqueN(q$dataset),n_K32_higher=sum(dd>0),mean_difference=if(length(dd))mean(dd)else NA_real_,median_difference=if(length(dd))median(dd)else NA_real_,p=if(is.null(test))NA_real_ else test$p.value,exact=exact,zero_differences=sum(dd==0),absolute_ties=sum(duplicated(abs(dd))),method=if(is.null(test))'NOT_TESTABLE'else test$method)
 }
 for(level in c('ALL','sample','dataset','source')){dd<-copy(d);dd[,unit:=if(level=='ALL')'ALL'else get(level)];cc<-dd[,{k<-K32;u<-ucell10[k];v<-usage10[k];list(n_full=.N,n_K32=sum(k),K32_fraction=mean(k),UCell_mean=if(length(u))mean(u)else NA_real_,UCell_median=if(length(u))median(u)else NA_real_,UCell_q25=if(length(u))quantile(u,.25)else NA_real_,UCell_q75=if(length(u))quantile(u,.75)else NA_real_,usage_mean=if(length(v))mean(v)else NA_real_,usage_median=if(length(v))median(v)else NA_real_,usage_q25=if(length(v))quantile(v,.25)else NA_real_,usage_q75=if(length(v))quantile(v,.75)else NA_real_,NMF_high=sum(NMF_high),UCell_high=sum(UCell_high),NMF_TP=sum(k&NMF_high),UCell_TP=sum(k&UCell_high))},by=unit];cc[,`:=`(branch=br,level=level,contribution=n_K32/sum(d$K32))];for(h in c('NMF','UCell')){cc[,(paste0(h,'precision')):=ifelse(n_K32>0,get(paste0(h,'_TP'))/n_K32,NA_real_)];cc[,(paste0(h,'recall')):=ifelse(get(paste0(h,'_high'))>0,get(paste0(h,'_TP'))/get(paste0(h,'_high')),NA_real_)]};covs[[paste(br,level)]]<-cc}
 for(field in intersect(c('nCount_RNA','nFeature_RNA','percent.mt'),names(d))){q<-d[,.(n=.N,value=mean(get(field),na.rm=TRUE)),by=.(sample,dataset,K32)];q[,`:=`(branch=br,measure=field)];qc[[paste(br,field)]]<-q}
